// @vitest-environment jsdom
import RAPIER from '@dimforge/rapier3d-compat';
import * as THREE from 'three';
import { beforeAll, describe, expect, it } from 'vitest';
import type { Course } from '../courses/types';
import { FEEDBACK_SOUNDS } from '../effects/FeedbackSystem';
import { InputManager } from '../input/InputManager';
import { Game } from './Game';

const STEP = 1 / 60;

/**
 * Synthetic hole: one big flat green with a cup radius that covers it, so the
 * opening putt always ends in the cup no matter how long it was charged.
 */
const LAB_COURSE: Course = {
  id: 'feedback-lab',
  name: 'Feedback Lab',
  themeId: 'green-hills',
  version: 1,
  holes: [
    {
      id: 'feedback-lab-1',
      name: 'Lab',
      par: 2,
      spawn: { x: 0, y: 0.5, z: -3 },
      cup: { position: { x: 0, y: 0.2, z: 3 }, radius: 30, captureDepth: 1.5 },
      bounds: { min: { x: -40, y: -8, z: -40 }, max: { x: 40, y: 24, z: 40 } },
      surfaces: [
        {
          id: 'lab-green',
          transform: { position: { x: 0, y: 0, z: 0 } },
          shape: 'box',
          size: { x: 60, y: 0.4, z: 60 },
          material: 'green',
        },
      ],
      obstacles: [],
    },
  ],
};

class MixerSpy {
  readonly played: string[] = [];
  readonly volumes: number[] = [];

  play(id: string): boolean {
    this.played.push(id);
    return true;
  }

  setMasterVolume(volume: number): void {
    this.volumes.push(volume);
  }
}

beforeAll(async () => {
  await RAPIER.init();
});

describe('match feedback', () => {
  it('fires particles and audio for the putt and for the cup', async () => {
    const overlay = document.createElement('div');
    document.body.append(overlay);
    const input = new InputManager({});
    const mixer = new MixerSpy();
    const game = await Game.create({
      renderer: {} as unknown as THREE.WebGLRenderer,
      camera: new THREE.PerspectiveCamera(60, 1.5, 0.1, 400),
      input,
      overlayRoot: overlay,
      courseId: LAB_COURSE.id,
      course: LAB_COURSE,
      holeCount: 1,
      humanCount: 1,
      botCount: 0,
      controlScheme: 'hold-to-charge',
      quality: 'high',
      volume: 70,
      audio: mixer,
    });

    expect(game.scene.getObjectByName('particle-pool')).toBeDefined();
    expect(mixer.volumes[0]).toBeCloseTo(0.7);

    const results = overlay.querySelector<HTMLElement>('.match-results');
    const status = overlay.querySelector<HTMLElement>('.hud-status');
    let charge = 0;
    for (let frame = 0; frame < 20000; frame += 1) {
      if (results?.hidden === false) break;
      if (charge > 0) {
        charge += 1;
        if (charge > 20) {
          window.dispatchEvent(new KeyboardEvent('keyup', { code: 'Space' }));
          charge = 0;
        }
      } else if (status?.dataset.ready === 'true') {
        window.dispatchEvent(new KeyboardEvent('keydown', { code: 'Space' }));
        charge = 1;
      }
      game.frame(STEP);
      input.endFrame();
    }

    expect(results?.hidden).toBe(false);
    expect(game.feedback.emittedFor('shot')).toBeGreaterThan(0);
    expect(game.feedback.emittedFor('holed')).toBeGreaterThan(0);
    expect(mixer.played).toContain(FEEDBACK_SOUNDS.shot);
    expect(mixer.played).toContain(FEEDBACK_SOUNDS.holed);

    game.setQuality('low');
    expect(game.feedback.quality).toBe('low');
    game.setVolume(30);
    expect(mixer.volumes.at(-1)).toBeCloseTo(0.3);
    expect(game.feedback.masterVolume).toBeCloseTo(0.3);

    game.dispose();
    input.dispose();
    overlay.remove();
  }, 120000);
});
